import 'reflect-metadata';
import { INestApplication, ValidationPipe } from '@nestjs/common';
import { Test } from '@nestjs/testing';
import request from 'supertest';
import { AppModule } from '../src/app.module';
import { DomainExceptionFilter } from '../src/bidding/domain/domain-exception.filter';

/**
 * ACCEPTANCE TESTS = the bar you must clear. Do NOT edit this file.
 * These are black-box HTTP tests. Implement the service + fee engine until they
 * are green, then ADD YOUR OWN unit tests (especially for the fee engine and the
 * RFP/bid state machine). See CHALLENGE.md for the full specification.
 */

const DAY_MS = 24 * 60 * 60 * 1000;
const futureIso = (offsetMs = DAY_MS): string =>
  new Date(Date.now() + offsetMs).toISOString();
const pastIso = (): string => new Date(Date.now() - DAY_MS).toISOString();
const sleep = (ms: number): Promise<void> =>
  new Promise((resolve) => setTimeout(resolve, ms));

describe('RFP & Bid Settlement (acceptance)', () => {
  let app: INestApplication;
  let http: ReturnType<typeof request>;

  beforeAll(async () => {
    const moduleRef = await Test.createTestingModule({
      imports: [AppModule],
    }).compile();

    app = moduleRef.createNestApplication();
    app.useGlobalPipes(
      new ValidationPipe({
        whitelist: true,
        forbidNonWhitelisted: true,
        transform: true,
      }),
    );
    app.useGlobalFilters(new DomainExceptionFilter());
    await app.init();
    http = request(app.getHttpServer());
  });

  afterAll(async () => {
    await app.close();
  });

  // ---- helpers -------------------------------------------------------------

  const createRfp = async (
    overrides: Partial<{
      title: string;
      budgetCapCents: number;
      submissionDeadline: string;
    }> = {},
  ) => {
    const res = await http.post('/rfps').send({
      title: 'Roof repair',
      budgetCapCents: 1_000_000,
      submissionDeadline: futureIso(),
      ...overrides,
    });
    return res;
  };

  const submitBid = async (
    rfpId: string,
    amountCents: number,
    vendorId = 'vendor-1',
  ) =>
    http.post(`/rfps/${rfpId}/bids`).send({
      vendorId,
      amountCents,
      lineItems: [{ description: 'work', quantity: 1, unitPriceCents: amountCents }],
    });

  /** Creates an OPEN rfp, a single bid, awards it. Returns ids. */
  const createAwardedRfp = async (amountCents: number) => {
    const rfp = await createRfp({ budgetCapCents: amountCents * 10 });
    const rfpId = rfp.body.id as string;
    const bid = await submitBid(rfpId, amountCents);
    const bidId = bid.body.id as string;
    await http.post(`/rfps/${rfpId}/award`).send({ bidId }).expect(200);
    return { rfpId, bidId };
  };

  // ---- RFP creation --------------------------------------------------------

  it('creates an RFP in OPEN status', async () => {
    const res = await createRfp();
    expect(res.status).toBe(201);
    expect(res.body).toMatchObject({
      title: 'Roof repair',
      budgetCapCents: 1_000_000,
      status: 'OPEN',
      awardedBidId: null,
    });
    expect(typeof res.body.id).toBe('string');
    expect(typeof res.body.createdAt).toBe('string');
  });

  it('rejects an RFP whose deadline is in the past (422)', async () => {
    const res = await createRfp({ submissionDeadline: pastIso() });
    expect(res.status).toBe(422);
    expect(res.body.error).toBe('RFP_DEADLINE_IN_PAST');
  });

  it('rejects malformed payloads at the boundary (400)', async () => {
    const res = await http
      .post('/rfps')
      .send({ title: '', budgetCapCents: -5, submissionDeadline: 'nope' });
    expect(res.status).toBe(400);
  });

  // ---- Bidding -------------------------------------------------------------

  it('404 when bidding on a non-existent RFP', async () => {
    const res = await submitBid('does-not-exist', 1000);
    expect(res.status).toBe(404);
    expect(res.body.error).toBe('RFP_NOT_FOUND');
  });

  it('rejects a bid whose amount does not equal the sum of line items (422)', async () => {
    const rfp = await createRfp();
    const res = await http.post(`/rfps/${rfp.body.id}/bids`).send({
      vendorId: 'vendor-1',
      amountCents: 9999,
      lineItems: [{ description: 'x', quantity: 2, unitPriceCents: 100 }], // sum = 200
    });
    expect(res.status).toBe(422);
    expect(res.body.error).toBe('BID_AMOUNT_MISMATCH');
  });

  it('accepts a valid bid as ACTIVE and not over budget', async () => {
    const rfp = await createRfp({ budgetCapCents: 500_000 });
    const res = await submitBid(rfp.body.id, 400_000);
    expect(res.status).toBe(201);
    expect(res.body.status).toBe('ACTIVE');
    expect(res.body.overBudget).toBe(false);
  });

  it('accepts an over-budget bid but flags it (allowed, not rejected)', async () => {
    const rfp = await createRfp({ budgetCapCents: 100_000 });
    const res = await submitBid(rfp.body.id, 250_000);
    expect(res.status).toBe(201);
    expect(res.body.status).toBe('ACTIVE');
    expect(res.body.overBudget).toBe(true);
  });

  it('supersedes a vendor previous active bid on resubmission', async () => {
    const rfp = await createRfp();
    const first = await submitBid(rfp.body.id, 100_000, 'vendor-1');
    const second = await submitBid(rfp.body.id, 120_000, 'vendor-1');
    expect(second.status).toBe(201);

    const detail = await http.get(`/rfps/${rfp.body.id}`).expect(200);
    const bids: Array<{ id: string; status: string }> = detail.body.bids;
    const firstBid = bids.find((b) => b.id === first.body.id);
    const secondBid = bids.find((b) => b.id === second.body.id);
    expect(firstBid?.status).toBe('SUPERSEDED');
    expect(secondBid?.status).toBe('ACTIVE');
    // Exactly one ACTIVE bid for that vendor.
    expect(bids.filter((b) => b.status === 'ACTIVE')).toHaveLength(1);
  });

  // ---- Award ---------------------------------------------------------------

  it('awards a bid: RFP becomes AWARDED, losers REJECTED', async () => {
    const rfp = await createRfp();
    const winner = await submitBid(rfp.body.id, 100_000, 'vendor-1');
    const loser = await submitBid(rfp.body.id, 110_000, 'vendor-2');

    const res = await http
      .post(`/rfps/${rfp.body.id}/award`)
      .send({ bidId: winner.body.id });
    expect(res.status).toBe(200);
    expect(res.body.status).toBe('AWARDED');
    expect(res.body.awardedBidId).toBe(winner.body.id);

    const detail = await http.get(`/rfps/${rfp.body.id}`).expect(200);
    const bids: Array<{ id: string; status: string }> = detail.body.bids;
    expect(bids.find((b) => b.id === winner.body.id)?.status).toBe('AWARDED');
    expect(bids.find((b) => b.id === loser.body.id)?.status).toBe('REJECTED');
  });

  it('award is idempotent for the same bid, conflicts for a different bid', async () => {
    const rfp = await createRfp();
    const a = await submitBid(rfp.body.id, 100_000, 'vendor-1');
    const b = await submitBid(rfp.body.id, 110_000, 'vendor-2');
    await http.post(`/rfps/${rfp.body.id}/award`).send({ bidId: a.body.id }).expect(200);

    // Re-awarding the same bid: idempotent success.
    await http.post(`/rfps/${rfp.body.id}/award`).send({ bidId: a.body.id }).expect(200);

    // Awarding a different bid after award: conflict.
    const conflict = await http
      .post(`/rfps/${rfp.body.id}/award`)
      .send({ bidId: b.body.id });
    expect(conflict.status).toBe(409);
    expect(conflict.body.error).toBe('ALREADY_AWARDED');
  });

  it('rejects bids on an RFP that is no longer OPEN (409)', async () => {
    const { rfpId } = await createAwardedRfp(100_000);
    const res = await submitBid(rfpId, 50_000, 'vendor-9');
    expect(res.status).toBe(409);
    expect(res.body.error).toBe('RFP_NOT_OPEN');
  });

  // ---- Settlement & fee engine --------------------------------------------

  it('settles with a PERCENTAGE fee, rounding half-up, conserving money', async () => {
    const { rfpId } = await createAwardedRfp(12_345);
    const res = await http.post('/settlements').send({
      rfpId,
      idempotencyKey: 'key-pct-1',
      feePolicy: { type: 'PERCENTAGE', bps: 250 }, // 2.50% of 12345 = 308.625 -> 309
    });
    expect(res.status).toBe(201);
    expect(res.body.awardedAmountCents).toBe(12_345);
    expect(res.body.platformFeeCents).toBe(309);
    expect(res.body.vendorPayoutCents).toBe(12_036);
    expect(res.body.platformFeeCents + res.body.vendorPayoutCents).toBe(12_345);
    expect(res.body.status).toBe('SETTLED');
  });

  it('settles with a marginal TIERED fee', async () => {
    const { rfpId } = await createAwardedRfp(100_000);
    const res = await http.post('/settlements').send({
      rfpId,
      idempotencyKey: 'key-tier-1',
      feePolicy: {
        type: 'TIERED',
        tiers: [
          { uptoCents: 50_000, bps: 300 }, // 3% on first 500.00 -> 1500
          { uptoCents: null, bps: 100 }, //   1% on the rest 500.00 -> 500
        ],
      },
    });
    expect(res.status).toBe(201);
    expect(res.body.platformFeeCents).toBe(2_000);
    expect(res.body.vendorPayoutCents).toBe(98_000);
  });

  it('settlement is idempotent on idempotencyKey, conflicts on a new key', async () => {
    const { rfpId } = await createAwardedRfp(50_000);
    const body = {
      rfpId,
      idempotencyKey: 'key-idem-1',
      feePolicy: { type: 'FLAT', cents: 1_000 },
    };
    const first = await http.post('/settlements').send(body);
    expect(first.status).toBe(201);

    const replay = await http.post('/settlements').send(body);
    expect([200, 201]).toContain(replay.status);
    expect(replay.body.id).toBe(first.body.id);
    expect(replay.body.platformFeeCents).toBe(first.body.platformFeeCents);

    // A different key for an already-settled RFP must conflict.
    const other = await http
      .post('/settlements')
      .send({ ...body, idempotencyKey: 'key-idem-2' });
    expect(other.status).toBe(409);
    expect(other.body.error).toBe('ALREADY_SETTLED');
  });

  it('409 when settling an RFP that is not AWARDED', async () => {
    const rfp = await createRfp();
    const res = await http.post('/settlements').send({
      rfpId: rfp.body.id,
      idempotencyKey: 'key-x',
      feePolicy: { type: 'FLAT', cents: 100 },
    });
    expect(res.status).toBe(409);
    expect(res.body.error).toBe('RFP_NOT_AWARDED');
  });

  // ---- Deadline (time-dependent) ------------------------------------------

  it('blocks bidding and awarding after the deadline passes', async () => {
    const rfp = await createRfp({ submissionDeadline: futureIso(800) });
    const rfpId = rfp.body.id as string;
    // Bid BEFORE the deadline: allowed.
    const early = await submitBid(rfpId, 100_000, 'vendor-1');
    expect(early.status).toBe(201);

    await sleep(1_100); // let the deadline pass

    const lateBid = await submitBid(rfpId, 120_000, 'vendor-2');
    expect(lateBid.status).toBe(422);
    expect(lateBid.body.error).toBe('BID_AFTER_DEADLINE');

    const lateAward = await http
      .post(`/rfps/${rfpId}/award`)
      .send({ bidId: early.body.id });
    expect(lateAward.status).toBe(422);
    expect(lateAward.body.error).toBe('AWARD_AFTER_DEADLINE');
  });

  // ---- Cancellation --------------------------------------------------------

  it('cancels an OPEN RFP: status CANCELLED, active bids REJECTED', async () => {
    const rfp = await createRfp();
    await submitBid(rfp.body.id, 100_000, 'vendor-1');
    await submitBid(rfp.body.id, 110_000, 'vendor-2');

    const res = await http.post(`/rfps/${rfp.body.id}/cancel`).send();
    expect(res.status).toBe(200);
    expect(res.body.status).toBe('CANCELLED');

    const detail = await http.get(`/rfps/${rfp.body.id}`).expect(200);
    const bids: Array<{ status: string }> = detail.body.bids;
    expect(bids.every((b) => b.status === 'REJECTED')).toBe(true);
  });

  it('cancel is idempotent and rejects new bids afterwards', async () => {
    const rfp = await createRfp();
    await http.post(`/rfps/${rfp.body.id}/cancel`).send().expect(200);
    // Idempotent: cancelling again is a no-op success.
    const again = await http.post(`/rfps/${rfp.body.id}/cancel`).send();
    expect(again.status).toBe(200);
    expect(again.body.status).toBe('CANCELLED');

    const bid = await submitBid(rfp.body.id, 50_000, 'vendor-1');
    expect(bid.status).toBe(409);
    expect(bid.body.error).toBe('RFP_NOT_OPEN');
  });

  it('cannot cancel a SETTLED RFP (409)', async () => {
    const { rfpId } = await createAwardedRfp(40_000);
    await http
      .post('/settlements')
      .send({ rfpId, idempotencyKey: 'k-cancel', feePolicy: { type: 'FLAT', cents: 100 } })
      .expect(201);
    const res = await http.post(`/rfps/${rfpId}/cancel`).send();
    expect(res.status).toBe(409);
    expect(res.body.error).toBe('RFP_NOT_CANCELLABLE');
  });

  // ---- Fee bounds ----------------------------------------------------------

  it('applies a minimum fee bound', async () => {
    const { rfpId } = await createAwardedRfp(1_000);
    const res = await http.post('/settlements').send({
      rfpId,
      idempotencyKey: 'k-min',
      feePolicy: { type: 'PERCENTAGE', bps: 250, minFeeCents: 50 }, // base 25 -> raised to 50
    });
    expect(res.status).toBe(201);
    expect(res.body.platformFeeCents).toBe(50);
    expect(res.body.vendorPayoutCents).toBe(950);
  });

  it('applies a maximum fee bound', async () => {
    const { rfpId } = await createAwardedRfp(100_000);
    const res = await http.post('/settlements').send({
      rfpId,
      idempotencyKey: 'k-max',
      feePolicy: { type: 'PERCENTAGE', bps: 500, maxFeeCents: 3_000 }, // base 5000 -> capped 3000
    });
    expect(res.status).toBe(201);
    expect(res.body.platformFeeCents).toBe(3_000);
    expect(res.body.vendorPayoutCents).toBe(97_000);
  });

  it('rejects a fee policy with min greater than max (422)', async () => {
    const { rfpId } = await createAwardedRfp(1_000);
    const res = await http.post('/settlements').send({
      rfpId,
      idempotencyKey: 'k-badbounds',
      feePolicy: { type: 'FLAT', cents: 100, minFeeCents: 200, maxFeeCents: 100 },
    });
    expect(res.status).toBe(422);
    expect(res.body.error).toBe('INVALID_FEE_POLICY');
  });

  // ---- Event log -----------------------------------------------------------

  it('records an ordered event log across the lifecycle', async () => {
    const rfp = await createRfp({ budgetCapCents: 1_000_000 });
    const rfpId = rfp.body.id as string;
    const a = await submitBid(rfpId, 50_000, 'vendor-1');
    await submitBid(rfpId, 60_000, 'vendor-2');
    await http.post(`/rfps/${rfpId}/award`).send({ bidId: a.body.id }).expect(200);
    await http
      .post('/settlements')
      .send({ rfpId, idempotencyKey: 'k-ev', feePolicy: { type: 'PERCENTAGE', bps: 250 } })
      .expect(201);

    const res = await http.get(`/rfps/${rfpId}/events`).expect(200);
    const events: Array<{ type: string; at: string; bidId: string | null }> = res.body;
    expect(events.map((e) => e.type)).toEqual([
      'RFP_CREATED',
      'BID_SUBMITTED',
      'BID_SUBMITTED',
      'RFP_AWARDED',
      'BID_REJECTED',
      'RFP_SETTLED',
    ]);
    const awarded = events.find((e) => e.type === 'RFP_AWARDED');
    expect(awarded?.bidId).toBe(a.body.id);
    expect(typeof events[0].at).toBe('string');
  });

  it('emits RFP_CANCELLED in the event log', async () => {
    const rfp = await createRfp();
    await submitBid(rfp.body.id, 10_000, 'vendor-1');
    await http.post(`/rfps/${rfp.body.id}/cancel`).send().expect(200);

    const res = await http.get(`/rfps/${rfp.body.id}/events`).expect(200);
    const types: string[] = res.body.map((e: { type: string }) => e.type);
    expect(types).toContain('RFP_CANCELLED');
    expect(types).toContain('BID_REJECTED');
  });

  // ---- Listing & pagination -----------------------------------------------

  it('lists RFPs with pagination metadata', async () => {
    const before = await http.get('/rfps?limit=100&offset=0&status=OPEN').expect(200);
    const total0: number = before.body.total;

    await createRfp();
    await createRfp();
    await createRfp();

    const after = await http.get('/rfps?limit=2&offset=0&status=OPEN').expect(200);
    expect(after.body.total).toBe(total0 + 3);
    expect(after.body.items).toHaveLength(2);
    expect(after.body.limit).toBe(2);
    expect(after.body.offset).toBe(0);

    // A second page returns different items.
    const page2 = await http.get('/rfps?limit=2&offset=2&status=OPEN').expect(200);
    const firstIds = new Set(after.body.items.map((r: { id: string }) => r.id));
    expect(page2.body.items.some((r: { id: string }) => firstIds.has(r.id))).toBe(false);
  });

  it('filters the list by status', async () => {
    const rfp = await createRfp();
    await http.post(`/rfps/${rfp.body.id}/cancel`).send().expect(200);

    const res = await http.get('/rfps?status=CANCELLED&limit=100').expect(200);
    const items: Array<{ id: string; status: string }> = res.body.items;
    expect(items.every((r) => r.status === 'CANCELLED')).toBe(true);
    expect(items.some((r) => r.id === rfp.body.id)).toBe(true);
  });

  it('rejects invalid list query params at the boundary (400)', async () => {
    await http.get('/rfps?status=BANANA').expect(400);
    await http.get('/rfps?limit=0').expect(400);
    await http.get('/rfps?limit=500').expect(400);
    await http.get('/rfps?offset=-1').expect(400);
  });
});
